use std::collections::HashMap
use std::fs

fn bal(m: HashMap<string, int>, name: string) -> Option<int> {
    m.get(name).cloned()
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut m: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt = p[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if m.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                m.insert(p[1], amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let amt = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                match bal(m, p[1]) {
                    None => println("error: unknown account ${p[1]}"),
                    Some(b) => {
                        if cmd == "deposit" {
                            m.insert(p[1], b + amt)
                            println("ok")
                        } else if amt > b {
                            println("error: insufficient funds")
                        } else {
                            m.insert(p[1], b - amt)
                            println("ok")
                        }
                    }
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt = p[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                match bal(m, p[1]) {
                    None => println("error: unknown account ${p[1]}"),
                    Some(fb) => {
                        match bal(m, p[2]) {
                            None => println("error: unknown account ${p[2]}"),
                            Some(tb) => {
                                if p[1] == p[2] {
                                    println("error: same account")
                                } else if amt > fb {
                                    println("error: insufficient funds")
                                } else {
                                    m.insert(p[1], fb - amt)
                                    m.insert(p[2], tb + amt)
                                    println("ok")
                                }
                            }
                        }
                    }
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            match bal(m, p[1]) {
                None => println("error: unknown account ${p[1]}"),
                Some(b) => println("${b}"),
            }
        }
    }
    let mut keys: Vec<string> = m.keys().collect()
    keys.sort()
    for k in keys {
        match bal(m, k) {
            Some(b) => println("${k} ${b}"),
            None => {}
        }
    }
}

